import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ source for custom GELU and global average pooling
custom_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // Approximate GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float cdf = 0.5f * (1.0f + erff(x * 0.70710678118f));
        output[idx] = x * cdf;
    }
}

torch::Tensor gelu_cuda(torch::Tensor input) {
    auto out = torch::zeros_like(input);
    int size = input.numel();

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    gelu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

__global__ void global_avg_pool2d_kernel(const float* __restrict__ input, float* __restrict__ output,
                                         int B, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * C) {
        int b = idx / C;
        int c = idx % C;

        float sum_val = 0.0f;
        // The data for (b, c) in NHWC is contiguous, so we can sum straightforwardly:
        int start = (b * C + c) * H * W;
        for(int i = 0; i < H * W; i++){
            sum_val += input[start + i];
        }
        sum_val /= (H * W);
        output[idx] = sum_val;
    }
}

torch::Tensor global_avg_pool2d_cuda(torch::Tensor input) {
    // input: [B, C, H, W]
    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto out = torch::zeros({B, C}, input.options());

    const int threads = 256;
    const int blocks = (B * C + threads - 1) / threads;

    global_avg_pool2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(), out.data_ptr<float>(),
        B, C, H, W
    );
    return out;
}
"""

custom_ops_cpp_source = r"""
torch::Tensor gelu_cuda(torch::Tensor input);
torch::Tensor global_avg_pool2d_cuda(torch::Tensor input);
"""

# Build the custom ops extension
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=custom_ops_cpp_source,
    cuda_sources=custom_ops_source,
    functions=["gelu_cuda", "global_avg_pool2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces GELU and global average pooling with custom CUDA kernels.
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.conv(x)
        x = self.custom_ops.gelu_cuda(x)
        x = self.custom_ops.global_avg_pool2d_cuda(x)
        return x
